def icon(name: str, cls: str = "", label: str | None = None) -> Markup:
    """Return an inline SVG. Decorative by default (aria-hidden); pass `label` for a meaningful icon."""
    a11y = f'role="img" aria-label="{Markup.escape(label)}"' if label else 'aria-hidden="true" focusable="false"'
    return Markup(
        f'<svg class="icon {cls}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" '
        f'stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" {a11y}>'
        f'{PATHS[name]}</svg>'
    )
